   * output ports.  Use named arguments to check subsets of the output ports.
   * @param acquisitionCommand method that will be called with the value of the outgoing data
   *        port 'acquisitionCommand'.
   */
  def check_concrete_output(acquisitionCommand: EIT_Acquisition_Session_Coordinator.AcquisitionCommand.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val acquisitionCommandValue: EIT_Acquisition_Session_Coordinator.AcquisitionCommand.Type = get_acquisitionCommand().get
