  def get_acquisitionCommand(): Option[EIT_Acquisition_Session_Coordinator.AcquisitionCommand.Type] = {
    val value: Option[EIT_Acquisition_Session_Coordinator.AcquisitionCommand.Type] = get_acquisitionCommand_payload() match {
